// ES 熔断器配置
define('ES_BREAKER_COOLDOWN', 30);       // 熔断冷却时间（秒）
define('ES_BREAKER_THRESHOLD', 3);       // 连续失败 N 次后熔断
define('ES_CONNECT_TIMEOUT', 1);         // 连接超时（秒）
define('ES_REQUEST_TIMEOUT', 3);         // 请求超时（秒）
define('ES_PING_TIMEOUT', 1);            // 健康检查超时（秒）

/**
 * ES 熔断器：检查 ES 是否已被熔断（冷却期内跳过请求）
 * @return bool true=ES 可用, false=已熔断
 */
function es_breaker_allow() { return \App\Service\System\ElasticService::breakerAllow(); }

/**
 * ES 熔断器：记录失败，达到阈值时触发熔断
 */
function es_breaker_fail() { \App\Service\System\ElasticService::breakerFail(); }

/**
 * ES 熔断器：请求成功，重置计数器
 */
function es_breaker_reset() { \App\Service\System\ElasticService::breakerReset(); }

/**
 * ES 通用请求（带超时 + 熔断器）
 * @return array|null 成功返回解析后的数组，失败返回 null
 */
function es_request($method, $url, $data = null) { return \App\Service\System\ElasticService::request($method, $url, $data); }

/**
 * ES 健康检查（快速 ping）
 * @return bool true=ES 可用, false=不可用
 */
function es_ping() { return \App\Service\System\ElasticService::ping(); }

/**
 * ES 是否可用（熔断器 + ping 一并检查，结果缓存 30s）
 * @return bool
 */
function es_available() { return \App\Service\System\ElasticService::available(); }

function create_index() { return \App\Service\System\ElasticService::createIndex(); }
function es_insert_one($vid, $name) { return \App\Service\System\ElasticService::insertOne(intval($vid), (string)$name); }
function bulk_insert($list) { return \App\Service\System\ElasticService::bulkInsert((array)$list); }
function search($keyword) { return \App\Service\System\ElasticService::search((string)$keyword); } 
function clear_index() { return \App\Service\System\ElasticService::clearIndex(); }

function es_stats() { return \App\Service\System\ElasticService::stats(); }

function es_count() { return \App\Service\System\ElasticService::count(); }
